<?php if (!defined('ABSPATH')) exit; get_header(); ?><main><?php smt_breadcrumbs(); ?><section class="ui-page-hero"><div class="container"><span class="eyebrow"><?php echo esc_html(smt_t('Search','بحث')); ?></span><h1><?php printf(esc_html(smt_t('Results for “%s”','نتائج البحث عن «%s»')),esc_html(get_search_query())); ?></h1><?php get_search_form(); ?></div></section><section class="section"><div class="container content-list"><?php if(have_posts()): while(have_posts()):the_post(); ?><article class="content-card"><span><?php echo esc_html(get_post_type_object(get_post_type())->labels->singular_name); ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),28)); ?></p></article><?php endwhile; the_posts_pagination(); else: ?><div class="empty-state"><h2><?php echo esc_html(smt_t('No results found','لا توجد نتائج')); ?></h2><p><?php echo esc_html(smt_t('Try a different keyword or contact our team for assistance.','جرّب كلمة بحث أخرى أو تواصل مع فريقنا للمساعدة.')); ?></p></div><?php endif; ?></div></section></main><?php get_footer(); ?>